61	/// ids (hex, base32) pass, base64 keys do not.
62	fn looks_random(token: &str) -> bool {
63	    let has = |f: fn(&char) -> bool| token.chars().any(|c| f(&c));
64	    if !(has(char::is_ascii_lowercase) && has(char::is_ascii_uppercase) && has(char::is_ascii_digit)) {
65	        return false;
66	    }
67	    let mut counts = [0u32; 128];
68	    for b in token.bytes() {
69	        counts[usize::from(b & 127)] += 1;
70	    }
71	    let n = token.len() as f64;
72	    let entropy: f64 =
73	        counts.iter().filter(|c| **c > 0).map(|c| f64::from(*c) / n).map(|p| -p * p.log2()).sum();
74	    entropy > 4.2
75	}
